INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Photosynthesis and the Global Carbon Cycle', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Plants play a central role in regulating the Earth''s climate through the process of photosynthesis. During this process, plants absorb carbon dioxide from the atmosphere and convert it, along with water and sunlight, into glucose and oxygen. Forests, often called the "lungs of the planet," absorb a substantial portion of the carbon dioxide produced by human activity each year. However, deforestation not only removes this vital carbon sink but also releases the carbon stored in trees back into the atmosphere when the wood decays or is burned. Scientists estimate that tropical deforestation alone accounts for a significant share of global greenhouse gas emissions. Reforestation projects have been proposed as a way to offset carbon emissions, but critics argue that newly planted forests take decades to absorb as much carbon as mature ones. Consequently, many researchers emphasize that protecting existing forests should be prioritized over planting new ones as a climate strategy.

【設問】
Forests absorb none of the carbon dioxide produced by human activity.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 1, '["設問は「Forests absorb none of the carbon dioxide produced by human activity.」という内容である。本文には森林が人為的に排出される二酸化炭素のかなりの部分を吸収するとあり、矛盾する。よってBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9401);
