INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The Invention of the Printing Press', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Before the mid-15th century, books in Europe were copied by hand, a process that was slow, expensive, and prone to error. The invention of the movable-type printing press by Johannes Gutenberg around 1440 transformed this landscape entirely. By arranging individual metal letters that could be reused, printers could produce multiple copies of a text far more quickly than scribes ever could. The Gutenberg Bible, completed around 1455, is often cited as the first major book produced using this technology. Within decades, printing presses spread across Europe, dramatically lowering the cost of books and increasing literacy rates among the general population. This wider access to written material is often credited with accelerating the spread of new ideas during the Renaissance and later the Reformation. Some historians argue that without the printing press, the rapid dissemination of Martin Luther''s writings, which challenged the Catholic Church, would have been far less effective.

【設問】
Before Gutenberg''s invention, books were primarily copied by hand.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「Before Gutenberg''s invention, books were primarily copied by hand.」という内容である。本文冒頭に、15世紀半ば以前は本が手書きで写されていたとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9402);
