INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Loss Aversion in Behavioral Economics', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Behavioral economists have long observed that people tend to feel the pain of a loss more intensely than the pleasure of an equivalent gain, a phenomenon known as loss aversion. In a classic experiment, participants who were given a mug were reluctant to sell it for less than a certain price, even though they had shown little interest in buying an identical mug moments earlier. This asymmetry challenges the traditional economic assumption that people make decisions purely by weighing objective costs and benefits. Loss aversion has been used to explain a wide range of real-world behaviors, from investors holding onto declining stocks too long to consumers being more motivated by the fear of missing a discount than by the discount itself. Marketers frequently exploit this tendency by framing offers in terms of potential losses rather than potential gains. Critics of behavioral economics argue that laboratory findings do not always translate perfectly to complex, real-world financial decisions.

【設問】
People generally feel the pain of a loss more intensely than the pleasure of an equivalent gain.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「People generally feel the pain of a loss more intensely than the pleasure of an equivalent gain.」という内容である。本文冒頭に、人は同等の利益から得る喜びよりも損失の痛みをより強く感じる傾向があるとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9407);
