INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Bird Migration and Navigation', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Many species of birds undertake extraordinary long-distance migrations each year, traveling thousands of miles between breeding and wintering grounds. Scientists have long been fascinated by how these birds manage to navigate such vast distances with remarkable accuracy, often returning to the exact same nesting site year after year. Research suggests that birds rely on multiple navigational cues, including the position of the sun and stars, visual landmarks such as coastlines and mountain ranges, and even the Earth''s magnetic field. Some studies indicate that certain birds possess specialized cells containing magnetite, a mineral that may allow them to detect magnetic fields directly. Young birds making their first migration appear to rely more heavily on an innate genetic program, while experienced adults seem to incorporate learned landmarks into their navigational strategy. Climate change and habitat loss along traditional migratory routes have raised concerns among conservationists about the future viability of these ancient journeys.

【設問】
