INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Phishing and Cybersecurity', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Phishing remains one of the most common and effective methods used by cybercriminals to steal sensitive information such as passwords and financial details. In a typical phishing attack, victims receive an email or message that appears to come from a trustworthy source, such as a bank or well-known company, urging them to click a link and enter personal information. These fraudulent messages often create a sense of urgency, warning recipients that their account will be suspended unless immediate action is taken. Security experts note that phishing attacks have become increasingly sophisticated, with some messages nearly indistinguishable from legitimate communications. Organizations have responded by implementing employee training programs designed to help staff recognize suspicious emails before clicking on embedded links. Despite these efforts, phishing continues to account for a substantial proportion of successful data breaches each year, partly because attackers constantly adapt their techniques to evade detection by spam filters and security software.

