INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Construction of the Egyptian Pyramids', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

The construction of the Great Pyramid of Giza, completed around 2560 BCE, remains one of the most impressive engineering achievements of the ancient world. Composed of an estimated 2.3 million limestone blocks, some weighing as much as several tons, the pyramid was built without the wheel or iron tools, which had not yet been developed in ancient Egypt. Archaeologists continue to debate exactly how workers transported such massive stones over long distances and lifted them to great heights during construction. One widely accepted theory suggests that workers used ramps, possibly a combination of straight and spiraling designs, to drag the blocks into position using sledges and ropes. Contrary to a popular historical misconception, evidence from workers'' villages near the pyramids suggests that the structures were built primarily by paid laborers and skilled craftsmen rather than enslaved people. These workers appear to have been organized into teams, with archaeological records indicating they received rations of bread, beer, and meat as compensation for their labor.

【設問】
The Great Pyramid was built using iron tools and the wheel.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 1, '["設問は「The Great Pyramid was built using iron tools and the wheel.」という内容である。本文には車輪も鉄の道具も当時のエジプトではまだ発達していなかったとあり、矛盾する。よってBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9417);
