INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Bias in Machine Learning Algorithms', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Machine learning algorithms are trained on large datasets to identify patterns and make predictions, but this process can inadvertently produce biased outcomes if the underlying training data reflects existing societal inequalities. For example, a hiring algorithm trained primarily on historical resumes from a company that has predominantly hired men for technical roles may learn to favor male applicants, even if gender is never explicitly included as a factor. Similarly, facial recognition systems have been shown in several studies to exhibit significantly higher error rates when identifying individuals with darker skin tones, largely because training datasets have historically underrepresented these groups. Addressing algorithmic bias requires careful attention not only to the diversity of training data but also to how algorithms are designed and evaluated after deployment. Some researchers advocate for regular audits of automated decision-making systems, particularly in high-stakes areas such as hiring, lending, and criminal justice, where biased outcomes can have serious consequences for affected individuals. Critics argue that technical fixes alone cannot fully resolve issues rooted in broader societal inequality.

【設問】
A hiring algorithm trained on biased historical data can learn to favor certain applicants even without gender being an explicit factor.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「A hiring algorithm trained on biased historical data can learn to favor certain applicants even without gender being an explicit factor.」という内容である。本文に、性別が明示的な要因として含まれていなくても、そのようなアルゴリズムが男性の応募者を優遇するよう学習しうるとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9418);
