INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The History of the Magnetic Compass', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

For centuries before the widespread use of satellite navigation, sailors relied on the magnetic compass to determine direction while at sea, particularly under conditions where landmarks and celestial bodies were obscured by clouds or fog. The compass likely originated in China, where lodestone, a naturally magnetized mineral, was first used for divination purposes before its navigational potential was recognized. By around the 11th century, Chinese sailors had begun using compasses for maritime navigation, and the technology gradually spread westward along trade routes to the Islamic world and eventually to Europe. European navigators adopted the compass during the medieval period, and it played an essential role in enabling the long transoceanic voyages of exploration beginning in the 15th century. Although modern ships primarily rely on satellite-based positioning systems, magnetic compasses remain standard equipment on vessels as a reliable backup in case electronic systems fail. Unlike electronic devices, a simple magnetic compass requires no power source and can function indefinitely under normal conditions.

【設問】
The magnetic compass is believed to have originated in China.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「The magnetic compass is believed to have originated in China.」という内容である。本文に、コンパスはおそらく中国で起源を持つとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9420);
