INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Public Transportation and Traffic Congestion', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

As cities around the world continue to grow, traffic congestion has become an increasingly pressing challenge for urban planners. Expanding road networks, once considered a straightforward solution, has often proven counterproductive due to a phenomenon known as induced demand, in which new roads simply attract more drivers rather than reducing overall congestion. In response, many cities have shifted their focus toward investing in public transportation systems, such as subways, light rail, and dedicated bus lanes, in an effort to encourage commuters to leave their cars at home. Studies of cities that have significantly expanded their public transit networks generally show reductions in per-capita car usage, along with associated decreases in air pollution. However, building effective transit systems requires substantial upfront investment and years of construction, making it a politically challenging undertaking for city governments facing budget constraints. Some cities have also experimented with congestion pricing, charging drivers a fee to enter busy areas during peak hours, a policy that has proven controversial but effective in reducing traffic in cities where it has been implemented.

【設問】
Expanding road networks always reduces traffic congestion in the long term.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 1, '["設問は「Expanding road networks always reduces traffic congestion in the long term.」という内容である。本文には誘発需要という現象により、新しい道路が単に運転者を増やすだけで、逆効果になることが多いとあり、常に渋滞を減らすという内容とは矛盾する。よってBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9421);
