INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Dietary Fiber and Digestive Health', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Dietary fiber, found primarily in fruits, vegetables, whole grains, and legumes, plays a significant role in maintaining digestive health, though it is not digested or absorbed by the human body in the way that other nutrients are. Instead, fiber passes largely intact through the digestive system, adding bulk to stool and promoting regular bowel movements. Nutritionists generally distinguish between two types of fiber: soluble fiber, which dissolves in water and has been associated with lowering cholesterol levels, and insoluble fiber, which does not dissolve and primarily aids in maintaining digestive regularity. Beyond its digestive benefits, some studies suggest that diets high in fiber may be associated with a reduced risk of certain chronic conditions, including heart disease and type 2 diabetes, though researchers caution that correlation does not necessarily indicate direct causation. Despite widespread recommendations to consume adequate fiber, surveys indicate that a majority of adults in many industrialized countries fall short of recommended daily intake levels, often due to diets low in fruits, vegetables, and whole grains.

【設問】
Fiber is fully digested and absorbed by the human body in the same way as other nutrients.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 1, '["設問は「Fiber is fully digested and absorbed by the human body in the same way as other nutrients.」という内容である。本文には食物繊維は他の栄養素とは異なりほとんど消化されずに消化管を通過するとあり、完全に消化・吸収されるという内容とは矛盾する。よってBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9425);
