INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The Ancient Silk Road', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

The Silk Road refers not to a single road but to a vast network of interconnected trade routes that linked China with the Mediterranean world, passing through Central Asia, Persia, and the Middle East. Established gradually beginning around the 2nd century BCE, these routes facilitated the exchange of goods such as silk, spices, precious metals, and, notably, ideas and technologies between distant civilizations. Silk, a luxury textile that China had learned to produce centuries earlier, became so closely associated with these trade routes that the entire network was later named after it by 19th-century geographers, though the term was not used by traders at the time. Beyond material goods, the Silk Road served as a conduit for the spread of religious and philosophical ideas, including Buddhism, which traveled from India to China largely along these routes. The network also inadvertently facilitated the spread of diseases, with some historians suggesting that trade routes contributed to the transmission of plague between Asia and Europe during the 14th century. Although overland trade eventually declined with the rise of maritime shipping routes, the Silk Road remains a powerful symbol of early global interconnectedness.

【設問】
The Silk Road refers to a single continuous road built specifically to transport silk.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 1, '["設問は「The Silk Road refers to a single continuous road built specifically to transport silk.」という内容である。本文には単一の道路ではなく、相互接続された交易路の広大なネットワークを指すとあり、単一の道路という内容とは矛盾する。よってBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9427);
