INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The Domestication of Dogs', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

The domestication of dogs is widely believed to represent the earliest instance of humans forming a close relationship with another species, though the precise timeline and location remain subjects of ongoing scientific debate. Genetic evidence suggests that dogs diverged from wolves at least 15,000 years ago, and possibly much earlier, well before the development of agriculture. One prominent theory proposes that domestication began when wolves that were less fearful of humans started scavenging near human settlements, gradually forming a mutually beneficial relationship in which humans provided food scraps in exchange for the wolves'' assistance in guarding camps or detecting approaching predators. Over many generations, humans likely began selectively breeding the friendliest and most cooperative wolves, a process that eventually produced animals significantly different in both appearance and temperament from their wild ancestors. Comparative studies have shown that dogs possess a unique ability among animals to interpret human gestures, such as pointing, an ability that even closely related wolves raised alongside humans generally struggle to develop. This capacity is thought to have emerged specifically through the selective pressures of domestication.

【設問】
Genetic evidence suggests dogs diverged from wolves at least 15,000 years ago.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「Genetic evidence suggests dogs diverged from wolves at least 15,000 years ago.」という内容である。本文に、遺伝的証拠から犬は少なくとも1万5000年前にオオカミから分岐したことが示唆されているとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9429);
