INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The History of the Wheel', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

The wheel is often cited as one of humanity''s most transformative inventions, yet it appeared surprisingly late in the archaeological record compared to other technologies such as agriculture and pottery. The earliest known wheels, dating to around 3500 BCE in Mesopotamia, were not used for transportation but rather as potter''s wheels for shaping clay vessels. It took several additional centuries before wheels were adapted for use on carts and chariots, likely because early wheels were solid wooden disks that were heavy and difficult to manufacture with precision. Interestingly, several advanced civilizations in the Americas, including the Maya, developed wheeled toys but never applied the wheel to transportation or labor, possibly because they lacked domesticated draft animals large enough to pull wheeled vehicles effectively. Once wheeled carts became widespread in Eurasia, they dramatically increased the efficiency of transporting goods and people, contributing to the growth of trade networks and, eventually, larger and more complex societies across the ancient world.

【設問】
The earliest known wheels were originally used as potter''s wheels rather than for transportation.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「The earliest known wheels were originally used as potter''s wheels rather than for transportation.」という内容である。本文に、最も古いとされる車輪は輸送用ではなく陶器を作るためのろくろとして使われたとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9431);
