INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The History of Anesthesia', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Before the development of effective anesthesia in the mid-19th century, surgical procedures were often agonizing ordeals performed on fully conscious patients, with surgeons prized primarily for the speed with which they could complete an operation. The first widely publicized public demonstration of ether as a surgical anesthetic took place in Boston in 1846, when dentist William Morton successfully rendered a patient unconscious for the removal of a neck tumor. News of this breakthrough spread rapidly across the medical community, and within just a few years, ether and later chloroform became standard practice in operating rooms throughout Europe and North America. Despite this progress, early anesthetics carried significant risks, as the precise dosage required to safely render a patient unconscious without causing respiratory failure was not yet well understood by physicians. Queen Victoria''s use of chloroform during childbirth in 1853 is often credited with helping to popularize anesthesia''s use, not only in surgery but also in obstetrics, despite continued reservations expressed by some clergy who viewed pain relief during labor as contrary to religious teaching.

【設問】
Before effective anesthesia, surgeons were often valued primarily for the speed of their operations.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「Before effective anesthesia, surgeons were often valued primarily for the speed of their operations.」という内容である。本文冒頭に、外科医は主に手術を完了する速さで評価されることが多かったとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9435);
