INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Tidal and Hydropower Energy', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Unlike solar and wind power, which depend heavily on weather conditions, tidal energy offers a highly predictable source of renewable electricity, since the timing of ocean tides can be calculated years in advance based on the gravitational interactions between the Earth, moon, and sun. Tidal power stations typically operate by capturing the kinetic energy of moving water as tides rise and fall, using underwater turbines that function similarly to wind turbines but are driven by water rather than air. One of the primary limitations of tidal energy is geographic, as effective tidal power generation requires locations with a particularly large difference between high and low tide, a characteristic found in relatively few coastal regions worldwide. The Bay of Fundy in Canada, which experiences some of the highest tidal ranges on Earth, has attracted significant interest from engineers seeking to develop large-scale tidal energy projects. Despite its predictability, tidal energy currently accounts for only a small fraction of global renewable electricity generation, largely due to the high upfront costs associated with constructing underwater infrastructure capable of withstanding the corrosive marine environment.

【設問】
Tidal energy is highly predictable because the timing of tides can be calculated years in advance.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「Tidal energy is highly predictable because the timing of tides can be calculated years in advance.」という内容である。本文冒頭に、潮の満ち引きの時期は何年も前から計算できるため、潮力エネルギーは高度に予測可能だとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9440);
