INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'Black Holes', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

A black hole forms when a massive star exhausts its nuclear fuel and collapses under the force of its own gravity, compressing an enormous amount of mass into an extremely small region of space. The resulting gravitational field becomes so intense that nothing, not even light, can escape once it crosses a boundary known as the event horizon, which is why black holes cannot be directly observed using conventional telescopes. Instead, astronomers typically detect black holes indirectly, by observing their gravitational influence on nearby stars or by detecting radiation emitted by superheated gas as it spirals toward the black hole before crossing the event horizon. In 2019, an international collaboration of scientists released the first-ever direct image of a black hole''s silhouette, located at the center of a distant galaxy, by combining data from radio telescopes positioned at multiple locations around the globe. Despite significant advances in observational technology, many fundamental questions about the physics occurring within a black hole''s event horizon remain unresolved, as the extreme conditions present make it exceptionally difficult to test theoretical predictions directly.

【設問】
Nothing, not even light, can escape a black hole once it crosses the event horizon.', NULL, '["本文の内容から明らかに正しい、または正しい内容が含まれている", "本文の内容から明らかに間違っている、または間違った内容が含まれている", "本文の内容からは、正しいか間違っているか判断できない"]', 0, '["設問は「Nothing, not even light, can escape a black hole once it crosses the event horizon.」という内容である。本文に、事象の地平線を越えると光さえも逃れられなくなるとある。よってAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 英語/長文読解）', 9442);
