INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('gab_english', '長文読解', 'The History of the Calendar', '次の文章を読み、設問の内容が本文から見て「正しい」「間違っている」「どちらとも言えない」のいずれであるかを判断しなさい。

Most calendars used throughout history have needed to reconcile two astronomical cycles that do not divide evenly into one another: the solar year, based on the Earth''s orbit around the sun, and the lunar month, based on the moon''s phases. The ancient Egyptian calendar largely disregarded the lunar cycle, instead basing its civil calendar on a fixed 365-day solar year divided into twelve months of thirty days each, with five additional days added at the end of the year. This system, while relatively simple, gradually drifted out of alignment with the actual solar year over time, since it failed to account for the additional quarter-day that the true solar year requires. The Julian calendar, introduced under Julius Caesar in 46 BCE, addressed this drift by adding a leap day every four years, though this correction was itself slightly imprecise, leading to a gradual accumulation of error over many centuries. This lingering discrepancy was eventually addressed by the Gregorian calendar, introduced in 1582, which refined the leap year rule and remains the most widely used civil calendar throughout the world today.

【設問】
